import React from 'react';
import { useParams } from 'react-router-dom';

export default function MachineDetailPage() {
  const { id } = useParams();
  return (
    <div style={{ padding: 20 }}>
      <h3>Данные машины - заглушка</h3>
      <p>ID машины: {id}</p>
    </div>
  );
}
